mapper.update:
UPDATE order_compensation_task
SET status = 1,
    processing_time = #{now},
    update_time = #{now}
WHERE id = #{id}
  AND status = 0
  AND next_retry_time <= #{now}

mapper.select:
SELECT *
FROM order_compensation_task
WHERE task_type = #{taskType}
  AND status = 0
  AND next_retry_time <= #{now}
ORDER BY next_retry_time ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE order_compensation_task
SET status = 2,
    processing_time = NULL,
    success_time = #{now},
    update_time = #{now}
WHERE id = #{id}
  AND status = 1
  AND processing_time = #{processingTime}

UPDATE order_compensation_task
SET status = 0,
    next_retry_time = #{nextRetryTime},
    processing_time = NULL,
    update_time = #{now}
WHERE task_type = #{taskType}
  AND status = 1
  AND processing_time <= #{staleBefore}
ORDER BY processing_time ASC, id ASC
LIMIT #{limit}
